 End do programa; Classes, subclasses e métodos virtuais
Um exemplo com uso de classes, subclasses e métodos virtuais: Begin
   Class Glyph;
      Virtual: Procedure print Is Procedure print;;
   Begin
   End; Glyph Class Char (c);
      Character c;
   Begin
      Procedure print;
        OutChar(c);
   End;

Glyph Class Char (c);
      Character c;
   Begin
      Procedure print;
        OutChar(c);
   End; Glyph Class Line (elements);
      Ref (Glyph) Array elements;
   Begin
      Procedure print;
      Begin
         Integer i;
         For i:= 1 Step 1 Until UpperBound (elements, 1) Do
            elements (i).print;
         OutImage;
      End;
   End; Ref (Glyph) rg;
   Ref (Glyph) Array rgs (1 : 4); !

! Main program;
   rgs (1):- New Char ('A');
   rgs (2):- New Char ('b');
   rgs (3):- New Char ('b');
   rgs (4):- New Char ('a');
   rg:- New Line (rgs);
   rg.print;
End; O exemplo acima tem uma superclasse (Glyph) com duas subclasses (Char e Line). Há um método virtual com duas implementações. A execução se inicia no bloco Main program.
